#!/usr/bin/env bash
# Source builds for ExecuTorch, llama.cpp, whisper.cpp, Darknet and the TFLM host library. Idempotent.
cd "$(dirname "$0")/.." && source scripts/env.sh
J=4; B=third_party/_build; mkdir -p $B logs
run(){ n=$1; shift; echo "[$(date +%T)] start $n"; if "$@" > logs/build_$n.log 2>&1; then echo "[$(date +%T)] ok $n"; else echo "[$(date +%T)] FAIL $n"; fi; }
llama(){ cmake -G Ninja -S third_party/llama.cpp -B $B/llama -DCMAKE_BUILD_TYPE=Release -DLLAMA_BUILD_TESTS=OFF -DLLAMA_BUILD_EXAMPLES=OFF -DLLAMA_BUILD_SERVER=OFF -DLLAMA_CURL=OFF -DGGML_NATIVE=OFF -DGGML_AVX2=ON -DGGML_FMA=ON -DGGML_F16C=ON && cmake --build $B/llama -j$J; }
whisper(){ cmake -G Ninja -S third_party/whisper.cpp -B $B/whisper -DCMAKE_BUILD_TYPE=Release -DGGML_NATIVE=OFF -DGGML_AVX2=ON -DGGML_FMA=ON -DGGML_F16C=ON -DWHISPER_BUILD_TESTS=OFF && cmake --build $B/whisper -j$J; }
darknet(){ make -C third_party/darknet -j$J CC="gcc -std=gnu11" CPP="g++" GPU=0 CUDNN=0 OPENCV=0 AVX=1 OPENMP=0 LIBSO=0; }
et_clone(){ d=third_party/executorch; [ -d $d/.git ] || git clone --depth 1 --branch v0.6.0 --recurse-submodules --shallow-submodules -j4 https://github.com/pytorch/executorch.git $d; }
et_build(){ d=third_party/executorch; cmake -G Ninja -S $d -B $B/executorch -DCMAKE_BUILD_TYPE=Release -DCMAKE_INSTALL_PREFIX=$PWD/$B/executorch/install -DCMAKE_POLICY_VERSION_MINIMUM=3.5 -DPYTHON_EXECUTABLE=$PWD/.envs/main/bin/python -DEXECUTORCH_BUILD_XNNPACK=ON -DEXECUTORCH_BUILD_EXTENSION_MODULE=ON -DEXECUTORCH_BUILD_EXTENSION_DATA_LOADER=ON -DEXECUTORCH_BUILD_EXTENSION_FLAT_TENSOR=ON -DEXECUTORCH_BUILD_EXTENSION_TENSOR=ON -DEXECUTORCH_BUILD_KERNELS_OPTIMIZED=OFF -DEXECUTORCH_BUILD_KERNELS_QUANTIZED=OFF -DEXECUTORCH_BUILD_EXECUTOR_RUNNER=ON -DEXECUTORCH_BUILD_DEVTOOLS=OFF -DEXECUTORCH_ENABLE_LOGGING=ON && cmake --build $B/executorch -j$J --target install; }
et_android(){ d=third_party/executorch; TC=$PWD/third_party/android/android-ndk-r27d/build/cmake/android.toolchain.cmake; for ABI in x86_64 arm64-v8a; do cmake -G Ninja -S $d -B $B/executorch_$ABI -DCMAKE_TOOLCHAIN_FILE=$TC -DANDROID_ABI=$ABI -DANDROID_PLATFORM=android-26 -DANDROID_STL=c++_static -DCMAKE_BUILD_TYPE=Release -DCMAKE_INSTALL_PREFIX=$PWD/$B/executorch_$ABI/install -DCMAKE_POLICY_VERSION_MINIMUM=3.5 -DPYTHON_EXECUTABLE=$PWD/.envs/main/bin/python -DEXECUTORCH_BUILD_XNNPACK=ON -DEXECUTORCH_BUILD_EXTENSION_MODULE=ON -DEXECUTORCH_BUILD_EXTENSION_DATA_LOADER=ON -DEXECUTORCH_BUILD_EXTENSION_FLAT_TENSOR=ON -DEXECUTORCH_BUILD_EXTENSION_TENSOR=ON -DEXECUTORCH_BUILD_KERNELS_OPTIMIZED=OFF -DEXECUTORCH_BUILD_KERNELS_QUANTIZED=OFF -DEXECUTORCH_BUILD_EXECUTOR_RUNNER=OFF -DEXECUTORCH_BUILD_DEVTOOLS=OFF -DEXECUTORCH_ENABLE_LOGGING=ON && cmake --build $B/executorch_$ABI -j$J --target install || return 1; cmake -G Ninja -S examples/08_executorch_cpp -B build/android/et_$ABI -DCMAKE_TOOLCHAIN_FILE=$TC -DANDROID_ABI=$ABI -DANDROID_PLATFORM=android-26 -DANDROID_STL=c++_static -DCMAKE_BUILD_TYPE=Release -DET_ROOT=$PWD/$B/executorch_$ABI/install -DET_SRC_PARENT=$PWD/third_party && cmake --build build/android/et_$ABI || return 1; done; }
for x in "${@:-llama whisper darknet et_clone et_build}"; do for t in $x; do run $t $t; done; done
